import { useIntervalFn } from '@vueuse/core';
import { Schema } from '../../../schema';
import { normalizeRoomTag, parseRoomTag } from '../../../util/room';
const RESERVED_TOP_LEVEL_KEYS = new Set(['世界', '庇护所', '房间', '主线任务', '楼层其他住户', '临时NPC']);
const initialData = Schema.parse({});
function isObjectRecord(val) {
    return !!val && typeof val === 'object' && !Array.isArray(val);
}
function sanitizeRoleObjectInPlace(role) {
    if (!isObjectRecord(role))
        return;
    const roomRaw = String(_.get(role, '所在房间', '') ?? '');
    const normalized = normalizeRoomTag(roomRaw);
    _.set(role, '所在房间', parseRoomTag(normalized).kind === 'none' ? '' : normalized);
}
function sanitizeStatDataForUi(raw) {
    if (!isObjectRecord(raw))
        return {};
    const next = _.cloneDeep(raw);
    for (const key of Object.keys(next)) {
        const val = next[key];
        if (RESERVED_TOP_LEVEL_KEYS.has(key)) {
            if (key === '临时NPC') {
                if (!isObjectRecord(val)) {
                    next[key] = {};
                    continue;
                }
                for (const npcName of Object.keys(val)) {
                    if (!isObjectRecord(val[npcName])) {
                        delete val[npcName];
                        continue;
                    }
                    sanitizeRoleObjectInPlace(val[npcName]);
                }
            }
            else if (!isObjectRecord(val)) {
                next[key] = {};
            }
            continue;
        }
        if (!isObjectRecord(val)) {
            delete next[key];
            continue;
        }
        sanitizeRoleObjectInPlace(val);
    }
    return next;
}
function hasDisplayableRoles(data) {
    const hasMainRoles = Object.entries(data).some(([key, value]) => !RESERVED_TOP_LEVEL_KEYS.has(key) && isObjectRecord(value));
    if (hasMainRoles)
        return true;
    const tempNpc = _.get(data, '临时NPC', {});
    return isObjectRecord(tempNpc) && Object.values(tempNpc).some(value => isObjectRecord(value));
}
function readMvuStatData(messageId) {
    try {
        const mvuData = Mvu.getMvuData({ type: 'message', message_id: messageId });
        const rawStatData = _.get(mvuData, 'stat_data', null);
        if (!isObjectRecord(rawStatData) || Object.keys(rawStatData).length === 0) {
            return { ok: false };
        }
        const statData = sanitizeStatDataForUi(rawStatData);
        const result = Schema.safeParse(statData);
        if (result.success && hasDisplayableRoles(result.data)) {
            return { ok: true, data: result.data, messageId };
        }
    }
    catch {
        // ignore
    }
    return { ok: false };
}
function resolveTargetMessageId(rawTarget) {
    if (rawTarget === 'latest')
        return 'latest';
    const numeric = Number(rawTarget);
    if (Number.isFinite(numeric) && numeric >= 0)
        return Math.trunc(numeric);
    return 'latest';
}
export function useMvuRoleStore(targetMessageId) {
    const data = ref(initialData);
    const ready = ref(false);
    const source = ref('default');
    const resolvedMessageId = ref('latest');
    const isDuringExtraAnalysis = ref(false);
    const refreshTicket = ref(0);
    const stopHandles = [];
    const { pause: pausePolling, resume: resumePolling } = useIntervalFn(() => {
        refresh();
    }, 1500, { immediate: false });
    function refresh() {
        const ticket = refreshTicket.value + 1;
        refreshTicket.value = ticket;
        const target = resolveTargetMessageId(targetMessageId.value);
        const current = readMvuStatData(target);
        if (current.ok) {
            data.value = current.data;
            source.value = target === 'latest' ? 'latest' : 'current';
            resolvedMessageId.value = current.messageId;
            ready.value = true;
        }
        else {
            const latest = target === 'latest' ? current : readMvuStatData('latest');
            if (latest.ok) {
                data.value = latest.data;
                source.value = 'latest';
                resolvedMessageId.value = latest.messageId;
                ready.value = true;
            }
            else {
                data.value = initialData;
                source.value = 'default';
                resolvedMessageId.value = 'latest';
                ready.value = false;
            }
        }
        try {
            isDuringExtraAnalysis.value =
                (typeof Mvu?.isDuringExtraAnalysis === 'function' && Mvu.isDuringExtraAnalysis() === true) ||
                    _.get(getVariables({ type: 'global' }) ?? {}, 'extra_analysis', false) === true;
        }
        catch {
            isDuringExtraAnalysis.value = false;
        }
        if (refreshTicket.value !== ticket)
            return;
    }
    const mainRoleEntries = computed(() => Object.entries(data.value)
        .filter(([key, value]) => !RESERVED_TOP_LEVEL_KEYS.has(key) && isObjectRecord(value))
        .map(([key, value]) => ({ key, role: value }))
        .sort((a, b) => {
        const aActive = String(a.role?.登场状态 ?? '').trim() === '登场' ? 0 : 1;
        const bActive = String(b.role?.登场状态 ?? '').trim() === '登场' ? 0 : 1;
        if (aActive !== bActive)
            return aActive - bActive;
        const aName = String(a.role?.姓名 ?? a.key ?? '').trim() || String(a.key);
        const bName = String(b.role?.姓名 ?? b.key ?? '').trim() || String(b.key);
        return aName.localeCompare(bName, 'zh-Hans-CN');
    }));
    const tempNpcEntries = computed(() => {
        const tempNpc = _.get(data.value, '临时NPC', {});
        if (!isObjectRecord(tempNpc))
            return [];
        return Object.entries(tempNpc)
            .filter(([, value]) => isObjectRecord(value))
            .map(([key, value]) => ({ key, role: value }))
            .sort((a, b) => String(a.key).localeCompare(String(b.key), 'zh-Hans-CN'));
    });
    const hasAnyRole = computed(() => mainRoleEntries.value.length > 0 || tempNpcEntries.value.length > 0);
    onMounted(() => {
        (async () => {
            await waitGlobalInitialized('Mvu');
            refresh();
            resumePolling();
            stopHandles.push(eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refresh), eventOn(Mvu.events.VARIABLE_INITIALIZED, refresh), eventOn(Mvu.events.VARIABLE_UPDATE_STARTED, refresh));
            if (typeof tavern_events !== 'undefined') {
                stopHandles.push(eventOn(tavern_events.MESSAGE_RECEIVED, refresh));
                stopHandles.push(eventOn(tavern_events.MESSAGE_UPDATED, refresh));
                stopHandles.push(eventOn(tavern_events.MESSAGE_EDITED, refresh));
                stopHandles.push(eventOn(tavern_events.MESSAGE_SWIPED, refresh));
                stopHandles.push(eventOn(tavern_events.MESSAGE_SENT, refresh));
                stopHandles.push(eventOn(tavern_events.CHAT_CHANGED, refresh));
            }
        })();
    });
    onBeforeUnmount(() => {
        pausePolling();
        stopHandles.forEach(stopHandle => stopHandle?.stop?.());
    });
    watch(targetMessageId, () => {
        refresh();
    });
    return {
        data,
        ready,
        source,
        resolvedMessageId,
        isDuringExtraAnalysis,
        hasAnyRole,
        mainRoleEntries,
        tempNpcEntries,
        refresh,
    };
}
